def inline(text):
 text=e(text)
 text=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',lambda m:'<a href="'+e(m[2],quote=True)+'">'+m[1]+'</a>',text)
 return re.sub(r'\*\*(.*?)\*\*',r'<strong>\1</strong>',text)
def markdown(text):
 out=[]
 for block in re.split(r'\n\s*\n',text.strip()):
  block=block.strip()
  if not block:continue
  if block.startswith('**') and 'CTA' in block.split('\n')[0]:
   out.append('<div class="actions">'+''.join(btn(label,url,i>0) for i,(label,url) in enumerate(re.findall(r'\[([^\]]+)\]\(([^)]+)\)',block)))+'</div>');continue
  if block.startswith('### '):out.append('<h3>'+inline(block[4:])+'</h3>');continue
  if block.startswith('## '):
   title=block[3:];anchor={'Columbus':'columbus','Harris County':'harris-county','Phenix City':'phenix-city','Smiths Station':'smiths-station','Auburn and Opelika':'auburn-opelika','Fort Benning relocation':'fort-benning'}.get(title,'')
   out.append('<h2'+(' id="'+anchor+'"' if anchor else '')+'>'+inline(title)+'</h2>');continue
  if '[' in block and not re.search(r'\]\(',block):continue
  out.append('<p>'+inline(block).replace('\n','<br>')+'</p>')
 return '\n'.join(out)
